create or replace function private.gst_sale_supply_type_resolve_v520(p_tenant_id uuid,p_customer_id uuid,p_document_date date,p_requested text default null) returns text language plpgsql stable security definer set search_path=public,private,pg_temp as $$ declare v_requested text:=nullif(upper(trim(coalesce(p_requested,''))),'');v_regtype text;begin if not exists(select 1 from public.customers c where c.tenant_id=p_tenant_id and c.id=p_customer_id and c.status='active') then raise exception 'Active customer not found';end if;select g.registration_type into v_regtype from public.gst_party_registrations_v520 g where g.tenant_id=p_tenant_id and g.party_type='customer' and g.party_id=p_customer_id and g.active and coalesce(p_document_date,current_date) between g.effective_from and coalesce(g.effective_to,'infinity'::date) order by g.effective_from desc,g.created_at desc limit 1;if v_requested is null then if v_regtype='sez' then raise exception 'SEZ customer requires explicit SEZWP or SEZWOP supply type';end if;if v_regtype='export' then raise exception 'Export customer requires explicit EXPWP or EXPWOP supply type';end if;if v_regtype in('registered','composition') then return 'B2B';end if;return 'B2C';end if;if v_requested not in('B2B','B2C','SEZWP','SEZWOP','EXPWP','EXPWOP','DEXP') then raise exception 'Invalid outward GST supply type %',v_requested;end if;if v_regtype='sez' and v_requested not in('SEZWP','SEZWOP') then raise exception 'SEZ customer must use SEZWP or SEZWOP';end if;if v_regtype='export' and v_requested not in('EXPWP','EXPWOP') then raise exception 'Export customer must use EXPWP or EXPWOP';end if;if v_regtype in('registered','composition') and v_requested='B2C' then raise exception 'Registered GST customer cannot be classified as B2C';end if;return v_requested;end $$;
create or replace function private.gst_sale_pos_resolve_v520(p_tenant_id uuid,p_customer_id uuid,p_location_id uuid,p_document_date date,p_supply_type text,p_items jsonb,p_requested text default null) returns text language plpgsql stable security definer set search_path=public,private,pg_temp as $$ declare v_requested text:=nullif(trim(coalesce(p_requested,'')),'');v_has_service boolean:=false;v_party_pos text;v_seller_state text;x jsonb;v_variant uuid;v_kind text;begin if v_requested is not null then return v_requested;end if;if upper(p_supply_type) in('EXPWP','EXPWOP') then return '96';end if;for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop v_variant:=nullif(x->>'variant_id','')::uuid;select coalesce(g.supply_kind,case when p.item_type='service' then 'service' else 'goods' end) into v_kind from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id left join lateral(select gp.supply_kind from public.gst_product_tax_profiles_v520 gp where gp.tenant_id=pv.tenant_id and gp.variant_id=pv.id and gp.active and coalesce(p_document_date,current_date) between gp.effective_from and coalesce(gp.effective_to,'infinity'::date) order by gp.effective_from desc,gp.created_at desc limit 1)g on true where pv.tenant_id=p_tenant_id and pv.id=v_variant;if v_kind='service' then v_has_service:=true;exit;end if;end loop;if v_has_service then return null;end if;select coalesce(g.place_of_supply_code,g.state_code,public.gst_state_code_resolve_v520(c.state)) into v_party_pos from public.customers c left join lateral(select gp.place_of_supply_code,gp.state_code from public.gst_party_registrations_v520 gp where gp.tenant_id=c.tenant_id and gp.party_type='customer' and gp.party_id=c.id and gp.active and coalesce(p_document_date,current_date) between gp.effective_from and coalesce(gp.effective_to,'infinity'::date) order by gp.effective_from desc,gp.created_at desc limit 1)g on true where c.tenant_id=p_tenant_id and c.id=p_customer_id;if v_party_pos is not null then return v_party_pos;end if;if upper(p_supply_type)='B2C' then select r.state_code into v_seller_state from public.gst_location_registrations_v520 m join public.gst_registrations_v520 r on r.id=m.registration_id and r.tenant_id=m.tenant_id where m.tenant_id=p_tenant_id and m.location_id=p_location_id and coalesce(p_document_date,current_date) between m.effective_from and coalesce(m.effective_to,'infinity'::date) order by m.effective_from desc limit 1;return v_seller_state;end if;return null;end $$;
create or replace function private.gst_sale_bridge_v520(p_priced_items jsonb,p_normalized_items jsonb,p_target_total numeric) returns jsonb language plpgsql immutable security definer set search_path=public,private,pg_temp as $$ declare x jsonb;v_out jsonb:='[]'::jsonb;v_raw numeric:=0;v_delta numeric;v_remaining numeric;v_gross numeric;v_discount numeric;v_take numeric;begin if jsonb_typeof(coalesce(p_priced_items,'[]'::jsonb))<>'array' or jsonb_typeof(coalesce(p_normalized_items,'[]'::jsonb))<>'array' then raise exception 'GST Sale bridge requires item arrays';end if;if jsonb_array_length(p_priced_items)<>jsonb_array_length(p_normalized_items) then raise exception 'GST Sale bridge item count mismatch';end if;select coalesce(sum(round(coalesce((j->>'quantity')::numeric,0)*coalesce((j->>'unit_price')::numeric,0),4)-coalesce((j->>'discount_amount')::numeric,0)),0) into v_raw from jsonb_array_elements(p_normalized_items)j;v_delta:=round(coalesce(p_target_total,0)-v_raw,4);v_remaining:=greatest(-v_delta,0);for x in select value from jsonb_array_elements(p_priced_items) loop v_gross:=round(coalesce((x->>'quantity')::numeric,0)*coalesce((x->>'unit_price')::numeric,0),4);v_discount:=coalesce((x->>'discount_amount')::numeric,0);if v_remaining>0 then v_take:=least(v_remaining,greatest(v_gross-v_discount,0));v_discount:=v_discount+v_take;v_remaining:=v_remaining-v_take;end if;v_out:=v_out||jsonb_build_array(x||jsonb_build_object('tax_rate',0,'discount_amount',round(v_discount,4)));end loop;if v_remaining>0.0001 then raise exception 'GST Sale bridge cannot represent the target total';end if;return jsonb_build_object('items',v_out,'additional_charges',case when v_delta>0 then v_delta else 0 end,'raw_total',round(v_raw,4),'bridge_delta',v_delta);end $$;
create or replace function private.gst_sale_reconcile_source_v520(p_tenant_id uuid,p_sale_id uuid,p_quote jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare qline jsonb;v_item public.sale_items%rowtype;v_ids jsonb:='[]'::jsonb;v_count integer;v_quote_count integer:=jsonb_array_length(coalesce(p_quote->'lines','[]'::jsonb));v_tax numeric:=coalesce((p_quote->'totals'->>'tax_collected_total')::numeric,0);v_sub numeric:=coalesce((p_quote->'totals'->>'subtotal')::numeric,0);v_disc numeric:=coalesce((p_quote->'totals'->>'discount')::numeric,0);v_taxable numeric:=coalesce((p_quote->'totals'->>'taxable_value')::numeric,0);v_round numeric:=coalesce((p_quote->'totals'->>'round_off')::numeric,0);v_grand numeric:=coalesce((p_quote->'totals'->>'grand_total')::numeric,0);v_cost numeric;v_recipient_gstin text:=nullif(p_quote->>'recipient_gstin','');begin select count(*) into v_count from public.sale_items si where si.tenant_id=p_tenant_id and si.sale_id=p_sale_id;if v_count<>v_quote_count then raise exception 'Persisted Sale line count does not match GST quote';end if;for qline in select value from jsonb_array_elements(p_quote->'lines') loop select * into v_item from public.sale_items si where si.tenant_id=p_tenant_id and si.sale_id=p_sale_id and si.variant_id=(qline->>'variant_id')::uuid;if not found then raise exception 'Persisted Sale line is missing for GST product %',qline->>'sku';end if;if abs(v_item.quantity-coalesce((qline->>'quantity')::numeric,0))>0.000001 then raise exception 'Persisted Sale quantity differs from GST quote for %',qline->>'sku';end if;if abs(v_item.unit_price-coalesce((qline->>'unit_price')::numeric,0))>0.0001 then raise exception 'Persisted Sale price changed after GST quote for %; retry the transaction',qline->>'sku';end if;update public.sale_items set subtotal=round(coalesce((qline->>'quantity')::numeric,0)*coalesce((qline->>'unit_price')::numeric,0),4),discount_amount=coalesce((qline->>'discount')::numeric,0),taxable_amount=coalesce((qline->>'taxable_value')::numeric,0),tax_rate=coalesce((qline->>'applied_gst_rate')::numeric,0),tax_amount=coalesce((qline->>'tax_amount')::numeric,0),line_total=coalesce((qline->>'line_total')::numeric,0),gross_profit=round(coalesce((qline->>'taxable_value')::numeric,0)-coalesce(cost_total,0),4) where id=v_item.id;v_ids:=v_ids||jsonb_build_array(v_item.id::text);end loop;select round(coalesce(sum(cost_total),0),4) into v_cost from public.sale_items where tenant_id=p_tenant_id and sale_id=p_sale_id;update public.sales set subtotal=round(v_sub,4),discount_total=round(v_disc,4),taxable_total=round(v_taxable,4),tax_total=round(v_tax,4),additional_charges=0,round_off=round(v_round,2),grand_total=round(v_grand,2),cost_total=v_cost,gross_profit=round(v_taxable-v_cost,4),customer_tax_number=coalesce(v_recipient_gstin,customer_tax_number),updated_at=now() where tenant_id=p_tenant_id and id=p_sale_id and status='posted';if not found then raise exception 'Posted Sale source disappeared during GST reconciliation';end if;return v_ids;end $$;
create or replace function public.gst_sale_create_v520(p_tenant_id uuid,p_customer_id uuid,p_sale_date date,p_due_date date,p_items jsonb,p_additional_charges numeric default 0,p_round_off numeric default 0,p_initial_payment numeric default 0,p_payment_method text default 'cash',p_payment_reference text default null,p_notes text default null,p_location_id uuid default null,p_device_id uuid default null,p_request_id text default null,p_supply_type text default null,p_place_of_supply_code text default null) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_req_payload jsonb;v_req_state jsonb;v_old_req jsonb;v_supply text;v_pos text;v_priced jsonb;v_normalized jsonb;v_quote jsonb;v_bridge jsonb;v_source jsonb;v_sale_id uuid;v_sale_number text;v_line_ids jsonb;v_snapshot uuid;v_journal uuid;v_document_number text;v_response jsonb;v_totals jsonb;begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;if not(private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'sales.manage')) then raise exception 'Sales permission required';end if;if not(private.gst_v520_has_access(p_tenant_id,'gst_compliance.calculate') or private.gst_v520_has_access(p_tenant_id,'gst_compliance.view')) then raise exception 'GST calculation permission required';end if;if p_location_id is null then raise exception 'Business location is required';end if;if coalesce(p_additional_charges,0)<>0 then raise exception 'Additional charges are not enabled for authoritative GST Sales until charge-level GST classification is configured';end if;if p_sale_date is null then raise exception 'Sale date is required';end if;if p_due_date is not null and p_due_date<p_sale_date then raise exception 'Due date cannot be before sale date';end if;if coalesce(p_initial_payment,0)<0 then raise exception 'Initial payment cannot be negative';end if;v_req_payload:=jsonb_build_object('customer_id',p_customer_id,'sale_date',p_sale_date,'due_date',p_due_date,'items',coalesce(p_items,'[]'::jsonb),'additional_charges',coalesce(p_additional_charges,0),'round_off',coalesce(p_round_off,0),'initial_payment',coalesce(p_initial_payment,0),'payment_method',lower(trim(coalesce(p_payment_method,''))),'payment_reference',nullif(trim(coalesce(p_payment_reference,'')),''),'notes',nullif(trim(coalesce(p_notes,'')),''),'location_id',p_location_id,'device_id',p_device_id,'supply_type',nullif(upper(trim(coalesce(p_supply_type,''))),''),'place_of_supply_code',nullif(trim(coalesce(p_place_of_supply_code,'')),'') );v_req_state:=private.gst_request_begin_v520(p_tenant_id,p_request_id,'gst.sale.create.v520',v_req_payload);if coalesce((v_req_state->>'existing')::boolean,false) then return v_req_state->'response';end if;v_old_req:=private.v47_request_existing(p_tenant_id,p_request_id,'sale.create');if v_old_req is not null then raise exception 'Request ID is already used by the legacy Sale path';end if;v_priced:=private.v482_price_sale_items(p_tenant_id,p_customer_id,p_items,p_location_id);v_normalized:=private.v481_normalize_items(p_tenant_id,v_priced,'sale');v_supply:=private.gst_sale_supply_type_resolve_v520(p_tenant_id,p_customer_id,p_sale_date,p_supply_type);v_pos:=private.gst_sale_pos_resolve_v520(p_tenant_id,p_customer_id,p_location_id,p_sale_date,v_supply,v_normalized,p_place_of_supply_code);v_quote:=public.gst_document_quote_v520(p_tenant_id,'sale',p_location_id,p_customer_id,p_sale_date,v_supply,v_pos,v_normalized,0,p_round_off);if coalesce((v_quote->>'ready_for_compliance')::boolean,false) is not true then raise exception 'GST Sale is not compliance-ready: %',coalesce(v_quote->'errors','[]'::jsonb)::text;end if;v_totals:=v_quote->'totals';if coalesce(p_initial_payment,0)>coalesce((v_totals->>'grand_total')::numeric,0)+0.005 then raise exception 'Payment cannot exceed GST Sale total';end if;v_bridge:=private.gst_sale_bridge_v520(v_priced,v_normalized,(v_totals->>'grand_total')::numeric);perform private.gst_authoritative_context_enter_v520(p_tenant_id,'sale');v_source:=public.sales_create_v483(p_tenant_id,p_customer_id,p_sale_date,p_due_date,v_bridge->'items',(v_bridge->>'additional_charges')::numeric,p_initial_payment,p_payment_method,p_payment_reference,p_notes,p_location_id,p_device_id,p_request_id);v_sale_id:=nullif(v_source->>'sale_id','')::uuid;if v_sale_id is null then raise exception 'GST Sale source could not be resolved';end if;perform private.gst_authoritative_context_bind_v520(v_sale_id);select s.sale_number into v_sale_number from public.sales s where s.tenant_id=p_tenant_id and s.id=v_sale_id and s.status='posted' for update;if v_sale_number is null then raise exception 'GST Sale source is not posted';end if;if exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='sale' and j.source_id=v_sale_id and j.status='posted') then raise exception 'Legacy Sale journal was created inside authoritative GST context';end if;if exists(select 1 from public.gst_legacy_document_markers_v520 m where m.tenant_id=p_tenant_id and m.source_type='sale' and m.source_id=v_sale_id) then raise exception 'Legacy GST evidence was created inside authoritative GST context';end if;v_line_ids:=private.gst_sale_reconcile_source_v520(p_tenant_id,v_sale_id,v_quote);v_snapshot:=private.gst_snapshot_create_v520(p_tenant_id,'sale',v_sale_id,v_sale_number,p_location_id,p_sale_date,v_quote,v_line_ids);v_journal:=private.gst_authoritative_journal_post_v520(p_tenant_id,v_snapshot);select s.document_number into v_document_number from public.gst_document_snapshots_v520 s where s.id=v_snapshot and s.tenant_id=p_tenant_id;if v_document_number is null then raise exception 'GST Sale legal document number was not captured';end if;v_response:=coalesce(v_source,'{}'::jsonb)||jsonb_build_object('success',true,'gst_engine',v_quote->>'engine','gst_status','POSTED','gst_supply_type',v_supply,'place_of_supply_code',v_quote->>'place_of_supply_code','sale_id',v_sale_id,'sale_number',v_sale_number,'invoice_number',v_document_number,'grand_total',(v_totals->>'grand_total')::numeric,'taxable_total',(v_totals->>'taxable_value')::numeric,'tax_total',(v_totals->>'tax_collected_total')::numeric,'cgst',(v_totals->>'cgst')::numeric,'sgst',(v_totals->>'sgst')::numeric,'utgst',(v_totals->>'utgst')::numeric,'igst',(v_totals->>'igst')::numeric,'cess',(v_totals->>'cess')::numeric,'recipient_rcm_tax_payable_total',coalesce((v_totals->>'recipient_rcm_tax_payable_total')::numeric,0),'gst_snapshot_id',v_snapshot,'journal_id',v_journal,'gst_ready_for_compliance',true);v_response:=private.gst_request_complete_v520(p_tenant_id,p_request_id,'gst.sale.create.v520','sale',v_sale_id,v_snapshot,v_journal,v_response);update public.transaction_requests_v47 set response=v_response where tenant_id=p_tenant_id and request_id=trim(p_request_id) and operation='sale.create';perform private.gst_authoritative_context_exit_v520();return v_response;end $$;
revoke all on function private.gst_sale_supply_type_resolve_v520(uuid,uuid,date,text) from public,anon,authenticated;revoke all on function private.gst_sale_pos_resolve_v520(uuid,uuid,uuid,date,text,jsonb,text) from public,anon,authenticated;revoke all on function private.gst_sale_bridge_v520(jsonb,jsonb,numeric) from public,anon,authenticated;revoke all on function private.gst_sale_reconcile_source_v520(uuid,uuid,jsonb) from public,anon,authenticated;grant execute on function private.gst_sale_supply_type_resolve_v520(uuid,uuid,date,text) to service_role;grant execute on function private.gst_sale_pos_resolve_v520(uuid,uuid,uuid,date,text,jsonb,text) to service_role;grant execute on function private.gst_sale_bridge_v520(jsonb,jsonb,numeric) to service_role;grant execute on function private.gst_sale_reconcile_source_v520(uuid,uuid,jsonb) to service_role;revoke all on function public.gst_sale_create_v520(uuid,uuid,date,date,jsonb,numeric,numeric,numeric,text,text,text,uuid,uuid,text,text,text) from public,anon;grant execute on function public.gst_sale_create_v520(uuid,uuid,date,date,jsonb,numeric,numeric,numeric,text,text,text,uuid,uuid,text,text,text) to authenticated,service_role;
insert into public.thq_schema_releases(migration_no,schema_version,release_name,notes) values(241,'5.2.0-foundation','Atomic Authoritative GST Sale','Adds the first v5.2 atomic Sale endpoint. It reuses THQ pricing, unit normalization, stock, serial/batch/warranty, origin/invoice numbering and cash-drawer paths, but central GST is the only tax calculator. The Sale, immutable GST evidence and component journal are committed as one transaction with strong request-payload idempotency; legacy generic GST posting/evidence is suppressed only inside the private authoritative context. Real additional charges remain blocked until charge-level GST classification exists.') on conflict(migration_no) do update set schema_version=excluded.schema_version,release_name=excluded.release_name,notes=excluded.notes;